datasources = {}
data = value['bucketDetail']
if data is None: return

#We can sometimes have a massive # of data points, so we will look for the top ten entries and filter those out. 
#We do it this way so that the table data still has all the data
self.view.custom.info = {"text": "Building detail chart data", "type": "INFO"}

limitRows = value['top']
if limitRows: data = system.dataset.deleteRows(data, [i for i in range(limitRows, data.rowCount)])

eqList = self.view.custom.showEqPaths or self.view.custom.eqList

res = []
total = 0.0

selectedBucket = self.view.custom.selectedBucket
if selectedBucket in ('QUALITY_LOSS', 'SPEED_LOSS'):
	catColName = 'Product_Code'
	catColValue = 'Duration_Secs'
else:
	catColName = 'State'
	catColValue = 'Duration_Secs'	

catList = list(set([data.getValueAt(i, catColName) for i in range(data.rowCount)]))

#This next part is used to sort the data_sources to create the pareto effect
catArray = [[catList[y]] + [0] for y in range(len(catList))]
total = 0.0

if data.rowCount > 0: data = system.dataset.sort(data, catColValue, False)

for row in range(data.rowCount):
	cat = data.getValueAt(row, catColName)
	if cat not in catList: continue
	durationSecs = data.getValueAt(row, catColValue) or 0.0
	catArray[catList.index(cat)][1] += durationSecs
	total += durationSecs

catData = system.dataset.toDataSet([catColName, catColValue], catArray)
catData = system.dataset.sort(catData, catColValue, False)	
catList = [catData.getValueAt(r, catColName) for r in range(catData.rowCount)]

if total:
	sum = 0

	for i in range(len(eqList)):
		res = []
		assetPath = eqList[i]
		linePath = system.kanoa.utilities.convertDatasetRowToJSON(system.kanoa.asset.getParentAsset('line', assetPath),0)['assetPath']
		lineName = system.kanoa.utilities.formatPath(linePath, {})			
		eqName = system.kanoa.utilities.formatPath(assetPath, {'drop':linePath})
		for cat in catList:		
			catDict = {'eqPath':assetPath, 'eqName':eqName, 'category': cat, 'duration': 0.0, 'percent': 0.0, 'sum': 0.0, 'tooltip': '', 'occurrences': 0}

			for r in range(data.rowCount):
				if eqList[i] != data.getValueAt(r, 'Equipment_Path'): continue
				if cat == data.getValueAt(r, catColName):
					duration = data.getValueAt(r, catColValue)
					minutes = int(round(duration / 60.0)) # was int w/o round, CLN 12/22/2022
					percent = duration / total
					sum += percent
					try:
						numCount = data.getValueAt(r, 'Count')
					except:
						numCount = 1
					tooltip = '{}\n{}\n{}\n{:,} minute{}\n{:.1%}\n{:,} Occurrence{}'.format(cat, lineName, eqName, minutes, '' if minutes == 1 else 's', percent, numCount, '' if numCount == 1 else 's')

					catDict = {'eqPath':assetPath, 'eqName':eqName, 'category': cat, 'duration': minutes, 'percent': percent, 'sum': sum, 'tooltip': tooltip }
					break

			res.append(catDict)

		datasources.update({'data_' + str(i):res})

if len(datasources) == 0: datasources.update({'data_0':[]})

self.view.custom.info = {"text": "Buildng detail chart pareto line", "type": "INFO"}

#We'll now build the pareto line	
resPareto = []		
if total > 0:
	sum = 0.0
	for row in range(catData.rowCount):
		paretoData = {'category': catData.getValueAt(row, catColName)}
		sum += catData.getValueAt(row, catColValue) / total
		paretoData.update({'sum': sum})
		resPareto.append(paretoData)

datasources.update({'pareto_data' :resPareto})
self.view.custom.info = {"text": "", "type": "INFO"}		

return datasources

