def buildUtilizationDataset(rowDicts):

	from com.inductiveautomation.ignition.common.util import DatasetBuilder
	from java.lang import String, Double, Integer
	from java.util import Date		

	builder = DatasetBuilder.newBuilder()
	builder.colNames('modeName', 'assetPath', 'assetId', 'itemId', 'itemName', 'workOrderName', 'startDate', 'endDate', 'modeTypeName', 'durationSecs')
	builder.colTypes(String, String, Integer,  Integer, String, String, Date, Date, String, Integer)

	for rowDict in rowDicts:
		builder.addRow(rowDict.get('modeName'), rowDict.get('assetPath'), rowDict.get('assetId'), rowDict.get('itemId'), rowDict.get('itemName'), rowDict.get('workOrderName'), rowDict.get('startDate'), rowDict.get('endDate'), rowDict.get('modeTypeName'), rowDict.get('durationSecs'))

	return builder.build()

data = system.kanoa.event.getAssetProductionEvents({'assetId': assetId, 'startDate': startDate, 'endDate': endDate, 'strictDates': True})
header = ['modeName', 'itemId', 'itemName', 'workOrderName', 'assetPath', 'assetId', 'assetName', 'startDate','endDate', 'durationSecs', 'modeTypeName']
rowDicts = []

for rowIndex in range(data.rowCount):
	rowDict = {columnName: data.getValueAt(rowIndex, columnName) for columnName in header}
	rowDict['endDate'] = rowDict['endDate'] or system.date.now()
	system.perspective.print("itemId' %s for assetId %s"%(rowDict['itemId'], rowDict['assetId']))

	if rowDict['modeName'] == 'Production':
		if data.getValueAt(rowIndex, 'itemId') is None:
			rowDict['modeName'] = 'Production Delay'
		else:
			pStart = rowDict['startDate']
			pEnd = rowDict['endDate']
			isUnscheduled = True

			for scheduleIndex in range(scheduleData.rowCount):
				sStart = scheduleData.getValueAt(scheduleIndex, 'startDate')
				sEnd = scheduleData.getValueAt(scheduleIndex, 'endDate') or system.date.now()

				if (
					(pStart >= sStart and pStart < sEnd) or
					(pEnd >= sStart and pEnd < sEnd) or
					(pStart < sStart and pEnd > sEnd)
				):
					isUnscheduled = False
					break

			if isUnscheduled:
				rowDict['modeName'] = 'Unscheduled Production'

	rowDict['durationSecs'] = system.date.secondsBetween(rowDict['startDate'], rowDict['endDate'])
	rowDicts.append(rowDict)

return buildUtilizationDataset(rowDicts)
